            elif mode==4: h.update(fh+b'  '+rel+b'\n')
            elif mode==5: h.update(rel+b' '+fh+b'\n')
            elif mode==6: h.update(fh)
            elif mode==7: h.update(data)
        variants.append(h.hexdigest())
    print(root, len(files))
    for i,x in enumerate(variants): print(i,x)
